function bodyTemp(c, ageMonths){
  c=+c; if(isNaN(c)) return {error:'请输入体温（°C）'};
  ageMonths=(ageMonths==null||ageMonths==='')?null:(+ageMonths);
  if(ageMonths!=null && isNaN(ageMonths)) return {error:'月龄须为数字'};
  var feverThresh = (ageMonths!=null && ageMonths<3) ? 38 : 37.3;
  var level, advice;
  if(c < 36.0) { level='体温偏低'; advice='注意保暖，若持续偏低请咨询医生。'; }
  else if(c < feverThresh) { level='正常'; advice='体温正常，无需特殊处理。'; }
  else if(c < 38.0) { level='低热'; advice='低热，建议多饮水、休息并监测。'; }
  else if(c < 39.0) { level='发热'; advice='发热，可物理降温，持续不退请就医。'; }
  else { level='高热'; advice='高热，请及时就诊。'; }
  return {c:c, level:level, advice:advice, feverThresh:feverThresh, infant:(ageMonths!=null&&ageMonths<3)};
}
var EXPORTS={bodyTemp:bodyTemp};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BodyTempForgePure = EXPORTS; }
